import { writeFile } from 'node:fs/promises';
import { join } from 'node:path';

import { resolvePackageHandle } from '../shared/packages-externals.mjs';

/**
 * Byte-for-byte reproduction of `getAssetFileContent` in
 * `packages/packages/tools/generate-wordpress-asset-file-webpack-plugin`. The "generated by
 * Webpack" wording is kept so the emitted files stay identical to the ones already committed to
 * the plugin tree and referenced by PHP.
 */
function renderAssetFile( entryHandle, dependencyHandles ) {
	const deps = dependencyHandles
		.filter( ( handle ) => handle !== entryHandle )
		.sort()
		.map( ( handle ) => `'${ handle }',` )
		.join( '\n\t\t' );

	return `<?php
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}
/**
 * This file is generated by Webpack, do not edit it directly.
 */
return [
	'handle' => '${ entryHandle }',
	'deps' => [
		${ deps }
	],
];
`;
}

/**
 * Writes `<entry>.asset.php` listing the WordPress script handles the bundle depends on, derived
 * from the requests that were externalized rather than bundled.
 *
 * Webpack walked the chunk's module graph; here the externalized requests are collected as the
 * bundler resolves them, which yields the same set because a request is externalized exactly when
 * it maps to a handle.
 */
export function wordpressAssetFilePlugin( { entryName, entryHandle, outputDir, extraRequests } ) {
	return {
		name: 'elementor-wordpress-asset-file',
		async writeBundle( _, bundle ) {
			const requests = new Set( extraRequests ?? [] );

			for ( const chunk of Object.values( bundle ) ) {
				for ( const request of chunk.imports ?? [] ) {
					requests.add( request );
				}
			}

			const handles = new Set();

			for ( const request of requests ) {
				const handle = resolvePackageHandle( request );

				if ( handle ) {
					handles.add( handle );
				}
			}

			await writeFile(
				join( outputDir, `${ entryName }.asset.php` ),
				renderAssetFile( entryHandle, [ ...handles ] ),
			);
		},
	};
}
